({
async approve(id,notes){const h=eval(load("helpers"));const code="import json;from pathlib import Path;p=Path('job-search/applications/"+id+"/verification.json');d=json.loads(p.read_text());assert not d.get('submitted');d.update(agent_fact_review=True,visual_review_pending=False);p.write_text(json.dumps(d,indent=2)+'\\n');p.with_name('review.md').write_text("+JSON.stringify(notes)+"+'\\n')";const r=await tools.exec_command({cmd:"python3 -c "+h.q(code),max_output_tokens:100});if(r.exit_code!==0)throw Error(r.output);},
async complete(tab,id){const h=eval(load("helpers")),w=eval(load("wf"));const r=await tools.exec_command({cmd:"cat "+h.q("job-search/wttj-documents/"+id+".json"),max_output_tokens:14000});const m=JSON.parse(r.output);await tools.mcp__t3_code__preview_open({tabId:"tab_7z"});text(await h.upload("tab_7z",id,"input[type=file]"));let verified=false;for(let n=0;n<4;n++){await new Promise(r=>setTimeout(r,2000));try{await w.verifyAttachment("tab_7z",id);verified=true;break;}catch(e){if(n===3)throw e;}}if(!verified)throw Error("No verified attachment");await tools.mcp__t3_code__preview_open({tabId:tab});if(m.answers){for(const [field,value]of Object.entries(m.answers))await h.ev(tab,"(()=>{const e=document.getElementById("+JSON.stringify(field)+");if(!e)throw Error('Missing field');e.focus();Object.getOwnPropertyDescriptor(e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(e,"+JSON.stringify(value)+");e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));e.blur();return {id:e.id,value:e.value}})()");await h.save("job-search/applications/"+id+"/answers.json",m.answers);await h.save("job-search/applications/"+id+"/final-form-state-connected.json",await h.inspect(tab));await h.ev(tab,"(()=>{const b=[...document.querySelectorAll('button')].find(b=>b.innerText==='Send application');if(!b||b.disabled)throw Error('Submit unavailable');b.click();return true})()");}else await eval(load("campaign")).send(tab,id,m.message);for(let n=0;n<3;n++){await new Promise(r=>setTimeout(r,n===0?2000:4000));if(await w.recordReceipt(tab,id))return true;}return false;}
})
